    auto barrier_token = mainloop_pipeline.producer_try_acquire(mainloop_pipe_producer_state); // try_wait stage 0

    // Issue the Mainloop loads
    CUTLASS_PRAGMA_NO_UNROLL
    while (k_tile_count > 0) {
